const lockIssueWorkflowV2Admission = `-- name: LockIssueWorkflowV2Admission :one

SELECT issue.id
FROM workspace
JOIN issue ON issue.workspace_id = workspace.id
WHERE workspace.id = $1 AND issue.id = $2
FOR KEY SHARE OF workspace, issue
`

type LockIssueWorkflowV2AdmissionParams struct {
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	IssueID     pgtype.UUID `json:"issue_id"`
}

// Accepted scope ---------------------------------------------------------
// Every v2 writer must call this in its transaction before admitting a
// command or concern record. Workspace/issue deletion takes FOR UPDATE on the
// same owner rows, so a writer either commits before the sweep or observes the
// missing owner after it; it cannot create an orphan behind the sweep.
func (q *Queries) LockIssueWorkflowV2Admission(ctx context.Context, arg LockIssueWorkflowV2AdmissionParams) (pgtype.UUID, error) {
	row := q.db.QueryRow(ctx, lockIssueWorkflowV2Admission, arg.WorkspaceID, arg.IssueID)
	var id pgtype.UUID
	err := row.Scan(&id)
	return id, err
}

