const lockWorkflowReviewerCommandAuthority = `-- name: LockWorkflowReviewerCommandAuthority :one
WITH locked_agent AS MATERIALIZED (
    SELECT reviewer_agent.id FROM agent AS reviewer_agent
    WHERE reviewer_agent.id = $1 AND reviewer_agent.workspace_id = $2 AND reviewer_agent.archived_at IS NULL
    FOR UPDATE OF reviewer_agent
), locked_task AS MATERIALIZED (
	SELECT task.id, task.agent_id, task.issue_id, task.workflow_action_id,
	       task.workflow_operation_id, task.workflow_branch_key
    FROM agent_task_queue AS task
    JOIN locked_agent ON locked_agent.id = task.agent_id
    WHERE task.id = $3 AND task.issue_id = $4 AND task.status = 'running'
    FOR UPDATE OF task
), locked_action AS MATERIALIZED (
	SELECT receipt.id
	FROM issue_workflow_action_receipt AS receipt
	JOIN locked_task ON locked_task.workflow_action_id = receipt.id
	WHERE receipt.workspace_id = $2
	  AND receipt.issue_id = $4
	  AND receipt.action_type = 'review_candidate'
	  AND receipt.operation_id = $5
	  AND receipt.state = 'settled'
	  AND receipt.bound_task_id = locked_task.id
	  AND locked_task.workflow_operation_id = receipt.operation_id
	  AND locked_task.workflow_branch_key = receipt.payload->>'branch_key'
	  AND receipt.payload->>'reviewer_id' = $1::text
	  AND receipt.payload->>'candidate_id' = $6::text
      AND (receipt.payload->>'scope_revision')::bigint = $7::bigint
    FOR UPDATE OF receipt
)
SELECT EXISTS (SELECT 1 FROM locked_action) AS authorized
`

type LockWorkflowReviewerCommandAuthorityParams struct {
	ActorID            pgtype.UUID `json:"actor_id"`
	WorkspaceID        pgtype.UUID `json:"workspace_id"`
	TaskID             pgtype.UUID `json:"task_id"`
	IssueID            pgtype.UUID `json:"issue_id"`
	OperationID        pgtype.UUID `json:"operation_id"`
	CandidateID        string      `json:"candidate_id"`
	BoundScopeRevision int64       `json:"bound_scope_revision"`
}

func (q *Queries) LockWorkflowReviewerCommandAuthority(ctx context.Context, arg LockWorkflowReviewerCommandAuthorityParams) (bool, error) {
	row := q.db.QueryRow(ctx, lockWorkflowReviewerCommandAuthority,
		arg.ActorID,
		arg.WorkspaceID,
		arg.TaskID,
		arg.IssueID,
		arg.OperationID,
		arg.CandidateID,
		arg.BoundScopeRevision,
	)
	var authorized bool
	err := row.Scan(&authorized)
	return authorized, err
}

const markWorkflowTaskResultReconciliationFailed = `-- name: MarkWorkflowTaskResultReconciliationFailed :one
UPDATE issue_workflow_action_receipt AS receipt
SET reconciliation_state = 'failed',
    last_error = $1,
    revision = receipt.revision + 1,
    updated_at = now()
FROM agent_task_queue AS task
WHERE task.id = $2
  AND task.workflow_action_id = receipt.id
  AND task.issue_id = receipt.issue_id
  AND receipt.bound_task_id = task.id
  AND receipt.workspace_id = $3
  AND receipt.issue_id = $4
  AND task.status = 'completed'
  AND receipt.action_type IN ('review_correction', 'review_candidate', 'verify_runtime_exact_release', 'verify_business_exact_release')
  AND receipt.state = 'settled'
  AND receipt.reconciliation_state <> 'failed'
  AND NOT EXISTS (
    SELECT 1 FROM issue_workflow_command AS command
    WHERE command.workspace_id = receipt.workspace_id AND command.issue_id = receipt.issue_id
      AND command.command_key = 'task/' || task.id::text ||
        CASE receipt.action_type WHEN 'review_correction' THEN '/correction-result'
          WHEN 'review_candidate' THEN '/review-result'
          WHEN 'verify_runtime_exact_release' THEN '/runtime-verification-result'
          ELSE '/business-verification-result' END
      AND command.state = 'processed'
  )
RETURNING receipt.id, receipt.workspace_id, receipt.issue_id, receipt.action_key, receipt.request_hash, receipt.command_id, receipt.action_type, receipt.state, receipt.revision, receipt.operation_id, receipt.decision_id, receipt.release_id, receipt.notification_id, receipt.target_key, receipt.payload, receipt.not_before, receipt.lease_token, receipt.lease_expires_at, receipt.attempt_count, receipt.max_attempts, receipt.committed_at, receipt.settled_at, receipt.last_error, receipt.created_at, receipt.updated_at, receipt.lease_count, receipt.effect_attempt_count, receipt.observation_failure_count, receipt.effect_key, receipt.effect_result, receipt.reconciliation_state, receipt.last_observed_at, receipt.bound_task_id
`

